// ==========================================
// 1. INITIALIZE SYSTEM MEMORY
// ==========================================
let currentMode = context.get('currentMode') || 0; 
let soc = context.get('soc') || 100;
let voltage = context.get('voltage') || 26.4;
let acLoad = context.get('acLoad') || 0;
let manualOverride = context.get('manualOverride') || 0;
let isWeatherBad = context.get('isWeatherBad') || false;

// Track both solar arrays independently in local memory slots
let solarWatts1 = context.get('solarWatts1') || 0;
let solarWatts2 = context.get('solarWatts2') || 0;

// ==========================================
// 2. PARSE INCOMING DATA PIPELINES (VIC-AWARE)
// ==========================================
if (msg.topic) {
    let lowerTopic = msg.topic.toLowerCase();

    if (lowerTopic.includes("soc")) {
        soc = Number(msg.payload);
        context.set('soc', soc);
    }
    if (lowerTopic.includes("voltage")) {
        voltage = Number(msg.payload);
        context.set('voltage', voltage);
    }
    if (lowerTopic.includes("ac/acout/l1/p") || lowerTopic.includes("consumption")) {
        acLoad = Number(msg.payload);
        context.set('acLoad', acLoad);
    }
    if (lowerTopic.includes("weather") || lowerTopic.includes("cloud") || lowerTopic.includes("forecast")) {
        if (msg.payload === "Overcast" || msg.payload === "Rain" || msg.payload > 70) { isWeatherBad = true; } 
        else { isWeatherBad = false; }
        context.set('isWeatherBad', isWeatherBad);
    }

    // MATCH VIC-SYSTEM SOLAR CHARGERS AUTOMATIC TOPICS:
    if (lowerTopic.includes("solarcharger")) {
        if (lowerTopic.includes("/0/") || lowerTopic.includes("solarcharger_0") || lowerTopic.includes("instance0")) {
            solarWatts1 = Number(msg.payload);
            context.set('solarWatts1', solarWatts1);
        } else {
            solarWatts2 = Number(msg.payload);
            context.set('solarWatts2', solarWatts2);
        }
    }
}

// Intercept raw switch wire movements from your Venus toggle
if (!msg.topic || msg.topic === "") {
    if (msg.payload === 1 || msg.payload === true || msg.payload === 101) { manualOverride = 1; }
    else if (msg.payload === 0 || msg.payload === false) { manualOverride = 0; }
    context.set('manualOverride', manualOverride);
}

// Math Aggregator: Calculate total generation and net energy balance
let totalSolarWatts = solarWatts1 + solarWatts2;
let netSolarBalance = totalSolarWatts - acLoad;

let dynamicLowerSoC = global.get("dynamicLowerSoC") || 20;
let targetMode = currentMode; 

// ==========================================
// 3. TARGET STATE CALCULATOR (Solar Watts vs Load Watts)
// ==========================================
if (manualOverride === 1) {
    targetMode = 0; // Manual Overwrite ON -> Force Grid Connect Immediately
    context.set('lastSentPayload', null); 
} else if (acLoad >= 1200) {
    targetMode = 0; // Hard load safety ceiling -> Use Grid to protect inverter components
} else {
    // 1. CRITICAL BATTERY FLOOR PROTECTION
    if (soc <= dynamicLowerSoC || voltage <= 23.8) {
        targetMode = 0; 
    } 

    // 2. CONDITIONAL SOLAR PRIORITY RUN ENGAGEMENT
    else if (isWeatherBad === false && soc >= (dynamicLowerSoC + 4) && voltage > 24.5 && netSolarBalance >= 50) {
        targetMode = 1; // Verified net energy surplus -> Safe to run Solar Run
    } 

    // 3. REAL-TIME DEFICIT DRIFT FALLBACK (The Net Energy Monitor)
    else if (isWeatherBad === true || (netSolarBalance < -200 && soc < 50)) {
        targetMode = 0; // House load out-paces solar -> Reconnect Grid cleanly
    } 

    // 4. BUFFER STATE HYSTERESIS HOLD
    else {
        targetMode = currentMode; 
    }
}

// ==========================================
// 4. FORCE SHORE POWER HARDWARE CONTROL GATE
// ==========================================
let lastSentPayload = context.get('lastSentPayload');

// NATIVE SYSTEM REGISTERS FOR BLUE HARDWARE NODES:
// 1 = True (Force the hardware to turn ON Shore Power Connect / Start Charging)
// 0 = False (Turn OFF Force Shore Power / Release control back to Solar priority)
let outputPayload = (targetMode === 0) ? 1 : 0; 

if (outputPayload === lastSentPayload) {
    return [null, null]; // Suppress duplicate loops
}

context.set('lastSentPayload', outputPayload);
currentMode = targetMode;
context.set('currentMode', currentMode);

msgMode = { payload: outputPayload, topic: "Force Shore Control" };
msgAlarm = { payload: (outputPayload === 1) ? 1 : 0 }; 

return [msgMode, msgAlarm];

// Initialize local tracking variables
let lowBatteryAlarm = msg.payload; 
let faultState = 0;
let statusMessage = "System Status Normal";
let statusColor = "green";

// Evaluate the incoming Victron Low Battery Alarm binary state
if (lowBatteryAlarm === 1 || lowBatteryAlarm === true) {
    faultState = 1;
    statusMessage = "WARNING: Battery Voltage Sagging Under Load!";
    statusColor = "red";
} else {
    faultState = 0;
    statusMessage = "System Status Normal";
    statusColor = "green";
}

// Display the text beautifully right under the node box on your workspace canvas
node.status({ fill: statusColor, shape: "dot", text: statusMessage });

// Send ONLY a clean raw number down the wire to the rigid Victron hardware node
msg.payload = faultState;
return msg;

let dateObj = new Date();
let currentHour = dateObj.getHours();

// ==========================================
// DAYLIGHT GATEKEEPER RULE
// ==========================================
// In Tennessee, winter sun rises around 7:15 AM and sets as early as 4:45 PM. 
// Summer sun rises around 5:30 AM and sets around 8:15 PM.
let isNighttime = false;

// Fetch the astronomical sunset time from background memory if available
let actualSunsetTime = global.get("actualSunsetTime") || 0;

if (actualSunsetTime > 0) {
    let sunsetHourObj = new Date(actualSunsetTime).getHours();
    // It's night if it's past sunset or before early morning twilight (6:00 AM)
    if (currentHour >= sunsetHourObj || currentHour < 6) {
        isNighttime = true;
    }
} else {
    // FALLBACK: If the API hasn't given us a timestamp yet, use standard seasonal hours
    let currentMonth = dateObj.getMonth(); // 0 = Jan, 9 = Oct
    let typicalWinterSunset = 17; // 5:00 PM
    let typicalSummerSunset = 20; // 8:00 PM

    let activeSunsetCeiling = (currentMonth >= 9 || currentMonth <= 1) ? typicalWinterSunset : typicalSummerSunset;

    if (currentHour >= activeSunsetCeiling || currentHour < 6) {
        isNighttime = true;
    }
}

// IF IT IS NIGHTTIME: Terminate immediately. Do not query the API or change daytime math.
if (isNighttime) {
    node.status({ 
        fill: "black", 
        shape: "ring", 
        text: "Night Mode Idle (API Asleep) | Hour: " + currentHour + ":00" 
    });
    return null; 
}

// ==========================================
// ACTIVE DAYLIGHT SOLAR LOGIC (Only runs when sun is up)
// ==========================================
let weatherCondition = "Clear";
let cloudCover = 0;
let sunsetTimestamp = 0;

if (msg && msg.payload) {
    if (msg.payload.weather && msg.payload.weather) {
        weatherCondition = msg.payload.weather.main;
    }
    if (msg.payload.clouds && msg.payload.clouds.all !== undefined) {
        cloudCover = msg.payload.clouds.all;
    }
    if (msg.payload.sys && msg.payload.sys.sunset) {
        sunsetTimestamp = msg.payload.sys.sunset * 1000;
    }
}

let now = Date.now();
let recommendedFloor = 20; // Default sunny day rule

// 1. BASELINE WEATHER REGULATION
if (weatherCondition === "Rain" || weatherCondition === "Thunderstorm" || weatherCondition === "Snow" || weatherCondition === "Drizzle") {
    recommendedFloor = 60; 
} else if (weatherCondition === "Clouds" || cloudCover > 50) {
    recommendedFloor = 40; 
}

// 2. SUNSET PROXIMITY BUFFERS
let sunsetDateText = "Unknown";
if (sunsetTimestamp > 0) {
    let hoursUntilSunset = (sunsetTimestamp - now) / (1000 * 60 * 60);
    sunsetDateText = new Date(sunsetTimestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});

    if (hoursUntilSunset <= 3 && hoursUntilSunset > 0 && cloudCover >= 75) {
        recommendedFloor = Math.max(recommendedFloor, 60); // Protect against empty-tank sunset storm
    } else if (hoursUntilSunset <= 2 && hoursUntilSunset > 0) {
        recommendedFloor = Math.max(recommendedFloor, 35); // General secure night floor
    }
} else {
    sunsetDateText = "Pending API";
}

// Save variables out to global storage
global.set("dynamicLowerSoC", recommendedFloor);
global.set("actualSunsetTime", sunsetTimestamp);

// Display active daylight tracking status
node.status({ 
    fill: "blue", 
    shape: "dot", 
    text: "Sunset: " + sunsetDateText + " | Target Floor: " + recommendedFloor + "%" 
});

return msg;
